public class Hello2View1 extends SPanel {     
    public Hello2View1() {         
        setLayout(new BorderLayout(12, 12));         
        JLabel l = new JLabel("What's your name?");         
        add(l, BorderLayout.WEST);         
        STextField t = new STextField();         
        t.setColumns(20);         
        t.setSelector("name");         
        t.setControlID(Hello2Controller.GOT_NAME);         
        add(t, BorderLayout.EAST);         
        add(new SButton(Hello2Controller.CHANGE_TO_FRED), BorderLayout.SOUTH);     
    } 
}
